-- Per-member module access. Existing accounts retain their current two tools;
-- newly invited accounts begin with the rooms tool only.
begin;

do $$
begin
  if not exists (
    select 1 from information_schema.columns
    where table_schema = 'public' and table_name = 'project_members' and column_name = 'allowed_tools'
  ) then
    alter table public.project_members
      add column allowed_tools text[] not null default array['rooms']::text[];
    update public.project_members set allowed_tools = array['rooms','equipment']::text[];
  end if;
  if not exists (
    select 1 from pg_constraint where conrelid = 'public.project_members'::regclass
      and conname = 'project_members_allowed_tools_check'
  ) then
    alter table public.project_members
      add constraint project_members_allowed_tools_check
      check (allowed_tools = array['rooms']::text[] or allowed_tools = array['rooms','equipment']::text[]);
  end if;
end $$;

create or replace function private.member_tool_allowed(p_project_id uuid, p_tool text)
returns boolean language sql stable security definer set search_path = '' as $$
  select exists (
    select 1 from public.project_members m
    join public.projects p on p.id = m.project_id
    where m.project_id = p_project_id and m.user_id = auth.uid()
      and m.status = 'active' and p.archived_at is null
      and (m.role = 'admin' or p_tool = any(m.allowed_tools))
  )
$$;
revoke all on function private.member_tool_allowed(uuid,text) from public, anon, authenticated;

create or replace function public.set_member_tools(
  p_project_id uuid, p_user_id uuid, p_allowed_tools text[]
) returns void language plpgsql security definer set search_path = '' as $$
begin
  perform 1 from public.projects where id = p_project_id for update;
  if not private.can_manage(p_project_id) then
    raise exception 'project_admin_required' using errcode = '42501';
  end if;
  if p_allowed_tools is null or not (
    p_allowed_tools = array['rooms']::text[]
    or p_allowed_tools = array['rooms','equipment']::text[]
  ) then
    raise exception 'invalid_tool_access';
  end if;
  update public.project_members set allowed_tools = p_allowed_tools, updated_at = now()
  where project_id = p_project_id and user_id = p_user_id;
  if not found then raise exception 'member_not_found'; end if;
end $$;
revoke all on function public.set_member_tools(uuid,uuid,text[]) from public, anon, authenticated;
grant execute on function public.set_member_tools(uuid,uuid,text[]) to authenticated;

-- Equipment typologies are stored server-side, not in a public JavaScript asset.
create table if not exists private.tool_catalog (
  tool text primary key,
  payload jsonb not null
);
revoke all on private.tool_catalog from public, anon, authenticated;
