create or replace function public.get_tool_data(p_project_id uuid, p_tool text)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare v_payload jsonb;
begin
  if not private.member_tool_allowed(p_project_id,p_tool) then
    raise exception 'tool_access_denied' using errcode = '42501';
  end if;
  select payload into v_payload from private.tool_catalog where tool = p_tool;
  if v_payload is null then raise exception 'tool_data_unavailable'; end if;
  return v_payload;
end $$;
revoke all on function public.get_tool_data(uuid,text) from public, anon, authenticated;
grant execute on function public.get_tool_data(uuid,text) to authenticated;

notify pgrst, 'reload schema';
commit;
